  <h1 className="mb-8 text-center text-3xl font-bold text-slate-800">
    สมาชิกกลุ่มของเรา
  </h1>
  <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3">
    {members.map((m) => (
